"""cmix_wrapped — single-file score-honest wrapper with cmix v21 binary
inlined as a base64-encoded gzip blob.

The decompressor extracts the binary to a temp file at first call, chmod +x,
and execs via subprocess. program.py is the only artifact in this directory
counted toward program_size (meta.json is excluded by the driver).

Build provenance: cmix v21 from https://github.com/byronknoll/cmix HEAD as of
2026-05-09, compiled with `g++ -O3 -DNDEBUG -march=native -w -std=c++14`
after adding `#include <cstdint>` to every .cpp under src/. Stripped, then
gzip -9. Cross-host determinism is NOT guaranteed across CPU
microarchitectures because -march=native bakes target ISA in. For a contest
submission, rebuild without -march=native (use -march=x86-64-v3 or similar
portable target) or vendor source and compile at decode time.
"""

